parameters.jsCode:
const items = $input.all();
if (!items || items.length === 0) return [];

// 1. 소중한 chatId 원본 보호
const splitItems = $items("Code: 파일ID 분할");
const firstSplit = splitItems[0]?.json || {};

const resultJson = {
  isMergeSuccess: true,
  chatId: firstSplit.chatId || '',
  caption: firstSplit.caption || '',
  mediaGroupId: firstSplit.mediaGroupId || ''
};

// 2. 스마트 MIME 판독기
function getMime(bin) {
  if (bin.mimeType && bin.mimeType !== 'application/octet-stream') return bin.mimeType;
  const ext = (bin.fileExtension || '').toLowerCase();
  const name = (bin.fileName || '').toLowerCase();
  if (ext === 'png' || name.includes('.png')) return 'image/png';
  if (ext === 'webp' || name.includes('.webp')) return 'image/webp';
  return 'image/jpeg';
}

let validImageCount = 0;

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const splitJson = splitItems[i]?.json || {};
  const idx = splitJson.index; // 1, 2, 3

  if (!item.binary || !item.binary.data) continue;

  try {
    // 3. n8n Filesystem 모드 버그 완벽 우회 (진짜 Base64 강제 추출)
    const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    const base64String = buffer.toString('base64');

    resultJson[`base64_${idx}`] = base64String;
    resultJson[`mime${idx}`] = getMime(item.binary.data);
    validImageCount++;
  } catch (error) {
    console.log("Buffer extract error:", error);
  }
}

// 4. 사진 3장 정상 병합 확인
if (validImageCount !== 3) {
  return [{
    json: {
      isMergeSuccess: false,
      isError: true,
      chatId: firstSplit.chatId || '',
      telegramSummary: '❗️이미지 병합 실패. 다시 전송해주세요.'
    }
  }];
}

// 5. 바이너리(파일) 덩어리를 버리고, 깨끗한 JSON 텍스트만 통과시킵니다.
return [{
  json: resultJson
}];

nodes.executeCode:
const splitData = $items("Code: 파일ID 분할")[0].json;
const resultJson = { isMergeSuccess: true, chatId: splitData.chatId || '', mediaGroupId: splitData.mediaGroupId || '' };
const binaryData = {};
const items = $input.all();

for (const item of items) {
  const idx = item.json.index;
  const bin = item.binary?.data;
  if (!bin || !idx) continue;
  binaryData[`image${idx}`] = bin;
  resultJson[`mime${idx}`] = bin.mimeType || 'image/png';
}

if (Object.keys(binaryData).length !== 3) {
  return [{ json: { isMergeSuccess: false, isError: true, chatId: splitData.chatId || '', telegramSummary: '❗️이미지 병합 실패. 다시 전송해주세요.' } }];
}
return [{ json: resultJson, binary: binaryData }];

parameters.jsonBody:
={
  "generationConfig": {
    "temperature": 0.1,
    "topK": 20,
    "topP": 0.9,
    "maxOutputTokens": 8192,
    "responseMimeType": "application/json"
  },
  "contents": [
    {
      "parts": [
        {
          "inlineData": {
            "mimeType": "{{ $json.mime1 }}",
            "data": "{{ $json.base64_1 }}"
          }
        },
        {
          "inlineData": {
            "mimeType": "{{ $json.mime2 }}",
            "data": "{{ $json.base64_2 }}"
          }
        },
        {
          "inlineData": {
            "mimeType": "{{ $json.mime3 }}",
            "data": "{{ $json.base64_3 }}"
          }
        },
        {
          "text": "당신은 KREAM 호가창 JSON 추출기입니다. 당신의 임무는 제공된 3장의 이미지에서 상품 식별 정보와 사이즈별 판매호가/구매호가/최근체결 데이터를 최대 5개까지 정확히 추출하여 JSON 객체 하나만 반환하는 것입니다.

사용자 캡션 원문:
{{ $json.caption }}

매우 중요:
- 첫 번째 이미지는 판매 입찰 화면입니다.
- 두 번째 이미지는 구매 입찰 화면입니다.
- 세 번째 이미지는 체결 거래 화면입니다.
- 절대 이 3개 역할을 서로 바꾸지 마세요.
- 첫 번째 이미지에서는 sell_quotes_top만 채우고, buy_quotes_top / recent_trades는 해당 이미지 기준으로 절대 추출 근거로 사용하지 마세요.
- 두 번째 이미지에서는 buy_quotes_top만 채우고, sell_quotes_top / recent_trades는 해당 이미지 기준으로 절대 추출 근거로 사용하지 마세요.
- 세 번째 이미지에서는 recent_trades만 채우고, sell_quotes_top / buy_quotes_top는 해당 이미지 기준으로 절대 추출 근거로 사용하지 마세요.

중요 규칙:
1. 반드시 JSON 객체만 출력하세요. 설명문, 마크다운, 코드블록, 주석 절대 금지.
2. 제공된 3장의 이미지는 위 순서대로 판매 입찰 / 구매 입찰 / 체결 거래 화면이므로, 역할을 추측하거나 바꾸지 말고 고정된 역할로만 해석하세요.
3. 보이지 않는 값은 절대 추측하지 마세요. 보이면 추출하고, 불명확하면 null 또는 빈 배열([])로 두세요.
4. 가격(price)은 반드시 정수 숫자로만 출력하세요. 쉼표, 원, 공백 제거.
5. 수량(qty)은 화면에 명확히 보일 때만 정수로 출력하고, 보이지 않거나 애매하면 null로 출력하세요.
6. date_text는 화면에 보이는 원문 그대로 넣으세요. 예: "오늘", "어제", "2일 전", "3시간 전".
7. 판매호가(sell_quotes_top)는 첫 번째 이미지에서만, 화면에 보이는 최상단부터 최대 5개 추출하세요. 일반적으로 낮은 가격순입니다.
8. 구매호가(buy_quotes_top)는 두 번째 이미지에서만, 화면에 보이는 최상단부터 최대 5개 추출하세요. 일반적으로 높은 가격순입니다.
9. 최근체결(recent_trades)은 세 번째 이미지에서만, 화면상 최상단(가장 최신)부터 최대 5개를 추출하세요.
10. 최근체결은 반드시 date_text가 함께 보일 때만 추출하세요. 날짜/시간 문구가 불명확하면 recent_trades에 넣지 마세요.
11. 사용자 캡션에 특정 사이즈가 보이면 그 사이즈를 우선 추출하되, 해당 사이즈 데이터가 없으면 화면에 보이는 전체 사이즈를 추출하세요.
12. product_name은 이미지에서 확인 가능한 상품명 또는 상품 식별명을 넣으세요. 캡션 전체 문장을 그대로 넣지 마세요.
13. caption_raw에는 사용자 캡션 원문을 그대로 넣으세요.
14. caption_product_code는 사용자 캡션에서 5자리 이상 연속 숫자가 보일 때만 문자열로 넣고, 없으면 null로 두세요.
15. target_sizes_requested는 사용자 캡션에서 인식 가능한 사이즈만 문자열 배열로 넣고, 없으면 빈 배열([])로 두세요.
16. target_margin_requested는 사용자 캡션에서 '3만원', '3.5만원', '목표 50000', '목표마진 50000', '마진 50000' 형태가 보일 때만 숫자로 넣고, 없으면 null로 두세요.
17. 사이즈 숫자는 매우 중요합니다. 특히 290과 295를 혼동하지 마세요. 마지막 숫자가 불명확하면 추측하지 말고 notes에 "size_unclear"를 넣고 size_confidence를 낮추세요.
18. size_confidence와 parse_confidence는 0~1 사이 숫자로만 출력하세요.
19. 절대 없는 데이터를 억지로 생성하지 마세요.

반드시 아래 스키마 형태의 JSON 객체 하나만 반환하세요.

{
  "product_name": "string or null",
  "caption_raw": "{{ $json.caption }}",
  "caption_product_code": "string or null",
  "target_sizes_requested": ["260", "280"],
  "target_margin_requested": 50000,
  "sizes": [
    {
      "size": "270",
      "sell_quotes_top": [
        { "price": 368000, "qty": 1 },
        { "price": 369000, "qty": 2 }
      ],
      "buy_quotes_top": [
        { "price": 350000, "qty": 1 },
        { "price": 348000, "qty": 4 }
      ],
      "recent_trades": [
        { "price": 365000, "date_text": "오늘", "qty": null },
        { "price": 360000, "date_text": "2일 전", "qty": null }
      ],
      "size_confidence": 0.9,
      "notes": []
    }
  ],
  "global_notes": [],
  "parse_confidence": 0.9
}"
        }
      ]
    }
  ]
}

