parameters.jsCode:
let geminiItem, mergeNode;
try {
  geminiItem = $items("HTTP: Gemini (상품/시세 추출)")[0];
  mergeNode = $items("If: 병합 정상 확인")[0].json;
} catch (e) {
  return [{
    json: {
      isError: true,
      telegramSummary: '❗️이전 노드 데이터 참조 에러 발생. 다시 시도해주세요.'
    }
  }];
}

const chatId = mergeNode.chatId || '';
const mediaGroupId = mergeNode.mediaGroupId || '';
const rawCaption = String(mergeNode.caption || '').trim();
const SYS_VERSION = 'V10.5.3 (보유가치 재설계 & 마진쿠션 프리패스)';

// ---------- 1) Gemini JSON 파싱 ----------
let parsed;
try {
  const rawText = geminiItem.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
  parsed = JSON.parse(String(rawText).replace(/```json|```/g, '').trim());
} catch (e) {
  return [{
    json: {
      isError: true,
      chatId,
      telegramSummary: '❗️AI 파싱 오류. 이미지를 다시 전송해주세요.'
    }
  }];
}

if (!parsed || !Array.isArray(parsed.sizes) || parsed.sizes.length === 0) {
  return [{
    json: {
      isError: true,
      chatId,
      telegramSummary: '❗️사이즈 데이터를 추출하지 못했습니다.'
    }
  }];
}

// ---------- 2) 공통 함수 ----------
function normalizeText(val) {
  return String(val || '').replace(/\s+/g, '').toLowerCase().trim();
}

function toNumber(val, def = 0) {
  if (val === null || val === undefined || val === '') return def;
  const num = Number(String(val).replace(/,/g, '').trim());
  return Number.isFinite(num) ? num : def;
}

function safeNum(v, d = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
}

function won(value) {
  return Number(value || 0).toLocaleString('ko-KR');
}

function ceil100(value) {
  return Math.ceil(Number(value || 0) / 100) * 100;
}

function floor100(value) {
  return Math.floor(Number(value || 0) / 100) * 100;
}

function clampScore(n) {
  return Math.max(0, Math.min(100, Math.round(n)));
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function tagScore(tag) {
  if (String(tag).includes('DIAMOND')) return 6;
  if (String(tag).includes('BLUE')) return 5;
  if (String(tag).includes('GREEN')) return 4;
  if (String(tag).includes('YELLOW')) return 3;
  if (String(tag).includes('ORANGE')) return 2;
  return 1;
}

function calcSettlement(price, feeMultiplier, fixedFeeWithVat) {
  if (price <= 0) return 0;
  return Math.ceil(((price * feeMultiplier) - fixedFeeWithVat) / 10) * 10;
}

function sumQty(arr = []) {
  return arr.reduce((sum, x) => {
    const q = x?.qty;
    if (q === null || q === undefined || q === '') return sum + 1;
    return sum + Math.max(1, safeNum(q, 1));
  }, 0);
}

function avgPrice(arr = []) {
  const nums = arr.map(x => safeNum(x?.price, 0)).filter(Boolean);
  if (!nums.length) return 0;
  return Math.round(nums.reduce((a, b) => a + b, 0) / nums.length);
}

function tradeRecencyWeight(dateText) {
  if (!dateText) return 0;

  const str = String(dateText).trim();

  if (str.includes('오늘') || str.includes('시간') || str.includes('분')) return 1.0;
  if (str.includes('어제') || str.includes('1일')) return 0.8;
  if (str.includes('2일')) return 0.6;
  if (str.includes('3일')) return 0.45;
  if (str.includes('4일')) return 0.3;

  // 절대 날짜 형식: 26/03/10, 2026/03/10, 2026-03-10
  const m = str.match(/^(\d{2,4})[\/\-\.](\d{1,2})[\/\-\.](\d{1,2})$/);
  if (m) {
    let year = Number(m[1]);
    const month = Number(m[2]);
    const day = Number(m[3]);

    if (year < 100) year += 2000;

    const parsedDate = new Date(year, month - 1, day);
    if (!Number.isNaN(parsedDate.getTime())) {
      const now = new Date();
      const diffMs = now.getTime() - parsedDate.getTime();
      const diffDays = diffMs / (1000 * 60 * 60 * 24);

      if (diffDays <= 1.5) return 1.0;
      if (diffDays <= 3) return 0.85;
      if (diffDays <= 7) return 0.65;
      if (diffDays <= 14) return 0.45;
      if (diffDays <= 30) return 0.28;
      if (diffDays <= 60) return 0.15;
      return 0.08;
    }
  }

  return 0.12;
}

function getQuotesArray(sizeObj, sellOrBuy) {
  if (sellOrBuy === 'sell') {
    if (Array.isArray(sizeObj.sell_quotes_top)) return sizeObj.sell_quotes_top;
    if (Array.isArray(sizeObj.sell_quotes)) return sizeObj.sell_quotes;
    return [];
  }
  if (Array.isArray(sizeObj.buy_quotes_top)) return sizeObj.buy_quotes_top;
  if (Array.isArray(sizeObj.buy_quotes)) return sizeObj.buy_quotes;
  return [];
}

// ---------- 2-1) 최소 방어 로직 추가 ----------
function extractRawCaptionSizes(caption) {
  if (!caption) return [];
  return [...new Set(
    String(caption)
      .replace(/[\/|,]/g, ' ')
      .split(/\s+/)
      .map(v => v.trim())
      .filter(v => /^(2[3-9][0-9]|300)$/.test(v))
  )];
}

function getSizeConflictNotes(rawCaptionSizes, ocrSizes) {
  const notes = [];
  for (const capSize of rawCaptionSizes) {
    if (ocrSizes.includes(capSize)) continue;
    const near = ocrSizes.find(o => Math.abs(Number(o) - Number(capSize)) === 5);
    if (near) {
      notes.push(`사이즈 충돌 감지: 캡션 ${capSize} / OCR ${near}`);
    }
  }
  return notes;
}

function sanitizeRecentTrades(trades = []) {
  return trades.filter(t =>
    t &&
    toNumber(t.price, 0) > 0 &&
    String(t.date_text || '').trim() !== ''
  );
}

function isSuspiciousPriceStructure({ buyQuote, sellQuote, recentTradeAvg }) {
  if (buyQuote > 0 && sellQuote > 0 && buyQuote > sellQuote) return true;
  if (recentTradeAvg > 0 && sellQuote > 0 && recentTradeAvg > sellQuote * 1.12) return true;
  if (recentTradeAvg > 0 && buyQuote > 0 && buyQuote > recentTradeAvg * 1.15) return true;
  return false;
}

function hasFreshRecentTrade(trades = []) {
  return trades.some(t => tradeRecencyWeight(t?.date_text) >= 0.45);
}

function getRecentAskTradeAlignmentBonus(sellQuote, recentTrades = []) {
  if (!(sellQuote > 0) || !Array.isArray(recentTrades) || recentTrades.length === 0) return 0;

  const topTrades = recentTrades.slice(0, 3);
  let bonus = 0;

  for (const t of topTrades) {
    const tradePrice = toNumber(t?.price, 0);
    const weight = tradeRecencyWeight(t?.date_text);

    if (tradePrice <= 0 || weight <= 0) continue;

    const gap = Math.abs(sellQuote - tradePrice);

    if (gap <= 1000) bonus = Math.max(bonus, weight >= 0.65 ? 22 : 16);
    else if (gap <= 2000) bonus = Math.max(bonus, weight >= 0.65 ? 14 : 10);
    else if (gap <= 3000) bonus = Math.max(bonus, weight >= 0.65 ? 8 : 5);
  }

  return bonus;
}

// ---------- 3) 사용자 목표마진 추출 ----------
function parseUserTargetMargin(caption) {
  if (!caption) return 0;
  const text = String(caption).replace(/,/g, ' ').trim();
  let m = text.match(/(\d+(?:\.\d+)?)\s*만\s*원?/i);
  if (m) return Math.round(Number(m[1]) * 10000);

  m = text.match(/(?:목표마진|목표|마진)\s*[:=]?\s*(\d{4,6})/i);
  if (m) return Number(m[1]);

  const lines = text.split(/\n+/).map(v => v.trim()).filter(Boolean);
  if (lines.length > 0) {
    m = lines[lines.length - 1].match(/^(\d{4,6})$/);
    if (m) return Number(m[1]);
  }

  const tokens = text.split(/\s+/).filter(Boolean);
  if (tokens.length > 0) {
    if (/^\d{4,6}$/.test(tokens[tokens.length - 1])) return Number(tokens[tokens.length - 1]);
  }

  return 0;
}

// ---------- 4) 캡션 파싱 ----------
function parseCaptionInfo(caption, availableSizes = []) {
  const result = {
    raw: caption || '',
    productCode: '',
    productText: '',
    targetSizes: [],
    userTargetMargin: parseUserTargetMargin(caption)
  };

  if (!caption) return result;

  const sizeSet = new Set(availableSizes.map(v => String(v).trim().toUpperCase()));

  let working = String(caption)
    .replace(/(\d+(?:\.\d+)?)\s*만\s*원?/gi, ' ')
    .replace(/(?:목표마진|목표|마진)\s*[:=]?\s*\d{4,6}/gi, ' ')
    .trim();

  const lineParts = working.split(/\n+/);
  if (lineParts.length > 0) {
    const trimmedLast = String(lineParts[lineParts.length - 1] || '').trim();
    if (/^\d{4,6}$/.test(trimmedLast)) {
      lineParts.pop();
      working = lineParts.join(' ').trim();
    }
  }

  const slashParts = working.split('/').map(v => v.trim()).filter(Boolean);
  let productArea = slashParts.length >= 2 ? slashParts[0] : working;

  const allTokens = working
    .replace(/[|]/g, ' ')
    .replace(/,/g, ' ')
    .split(/\s+/)
    .map(v => v.trim())
    .filter(Boolean);

  const productTokens = productArea
    .replace(/[|]/g, ' ')
    .replace(/,/g, ' ')
    .split(/\s+/)
    .map(v => v.trim())
    .filter(Boolean);

  const codeToken =
    productTokens.find(t => /^\d{5,}$/.test(t)) ||
    allTokens.find(t => /^\d{5,}$/.test(t));

  if (codeToken) result.productCode = codeToken;

  const pickedSizes = [];
  for (const token of allTokens) {
    const up = token.toUpperCase();
    if (sizeSet.has(up)) pickedSizes.push(up);
  }
  result.targetSizes = [...new Set(pickedSizes)];

  let textCandidate = working;
  if (result.productCode) {
    textCandidate = textCandidate.replace(new RegExp(`\\b${result.productCode}\\b`, 'g'), ' ');
  }
  for (const size of result.targetSizes) {
    textCandidate = textCandidate.replace(new RegExp(`\\b${size}\\b`, 'gi'), ' ');
  }

  result.productText = textCandidate.replace(/[\/|,]/g, ' ').replace(/\s+/g, ' ').trim();
  return result;
}

const availableSizes = parsed.sizes.map(s => String(s.size || '').trim()).filter(Boolean);
const rawCaptionSizes = extractRawCaptionSizes(rawCaption);
const sizeConflictNotes = getSizeConflictNotes(rawCaptionSizes, availableSizes);

const captionInfo = parseCaptionInfo(rawCaption, availableSizes);
const requestedSizes = captionInfo.targetSizes;
const userTargetMargin = captionInfo.userTargetMargin;

// ---------- 5) 상품 매칭 ----------
const geminiProductName = String(parsed.product_name || '').trim();
const matchCandidates = [...new Set([captionInfo.productCode, captionInfo.productText, geminiProductName].filter(Boolean).map(normalizeText))];
const priceList = $input.all().map(item => item.json);
let matchedRow = null;
let matchedKey = '';

for (const candidate of matchCandidates) {
  matchedRow = priceList.find(row => normalizeText(row['키워드']) === candidate) ||
               priceList.find(row => normalizeText(row['상품명']) === candidate) ||
               priceList.find(row => {
                 const k = normalizeText(row['키워드']);
                 const n = normalizeText(row['상품명']);
                 return (k && (candidate.includes(k) || k.includes(candidate))) ||
                        (n && (candidate.includes(n) || n.includes(candidate)));
               });
  if (matchedRow) {
    matchedKey = candidate;
    break;
  }
}

let productName = matchedRow
  ? (matchedRow['상품명'] || matchedKey || geminiProductName || captionInfo.productCode || rawCaption)
  : (captionInfo.productCode || captionInfo.productText || geminiProductName || rawCaption);

const productCode = matchedRow
  ? (matchedRow['키워드'] || captionInfo.productCode || matchedKey || '')
  : (captionInfo.productCode || matchedKey || '');

if (!matchedRow) {
  return [{
    json: {
      isError: true,
      chatId,
      telegramSummary: `❗️[매칭 실패] 단가표에 없는 상품입니다.\n인식명: ${productName}`
    }
  }];
}

// ---------- 6) 비용 구조 ----------
const supply = toNumber(matchedRow['영산공급가'], 0);
const pLog = toNumber(matchedRow['매입물류비'], 3500);
const kLog = toNumber(matchedRow['크림물류비'], 3500);
const inventoryRiskCost = toNumber(matchedRow['재고리스크비용'], 3000);

const absoluteMinMargin = Math.max(10000, toNumber(matchedRow['절대최소마진'], 10000));
const safeBiddingMargin = Math.max(15000, absoluteMinMargin + 5000);
const premiumMinMargin = Math.max(30000, toNumber(matchedRow['프리미엄최소마진'], 30000));
const premiumHighMargin = Math.max(50000, toNumber(matchedRow['프리미엄상단마진'], 50000));
const standardMidMargin = Math.max(20000, toNumber(matchedRow['일반중간마진'], 20000));

const feeMultiplier = 0.934;
const fixedFeeWithVat = 2750;
const totalCost = supply + pLog + inventoryRiskCost;

if (supply <= 0) {
  return [{
    json: {
      isError: true,
      chatId,
      telegramSummary: `❗️공급가가 0원입니다.`
    }
  }];
}

function calcMargin(price) {
  return price <= 0 ? 0 : calcSettlement(price, feeMultiplier, fixedFeeWithVat) - totalCost - kLog;
}

function getPriceForMargin(targetMargin) {
  return ceil100((targetMargin + totalCost + kLog + fixedFeeWithVat) / feeMultiplier);
}

// ---------- 7) 방어선 차등화 엔진 ----------
function getDefensePriceByMarket({
  itemClass,
  targetPrice,
  minDefensePrice,
  sellQuote,
  recentTradeAvg,
  scarcityScore,
  turnoverScore,
  buyDepthScore,
  sellPressureScore,
  absoluteMinMargin,
  premiumMinMargin,
  calcMargin
}) {
  const basePrice = itemClass.includes('희소') ? targetPrice : Math.max(targetPrice, minDefensePrice);
  const scoreDelta = (scarcityScore * 0.22) + (turnoverScore * 0.28) + (buyDepthScore * 0.25) - (sellPressureScore * 0.30);
  const rawAdjustment = Math.round(scoreDelta * 60);
  let adjustedPrice = basePrice + rawAdjustment;

  if (recentTradeAvg > 0) adjustedPrice = Math.min(adjustedPrice, recentTradeAvg + (itemClass.includes('희소') ? 4000 : 2000));
  if (sellQuote > 0) {
    const sellCap = sellQuote - 1000;
    if (sellCap > 0) adjustedPrice = Math.min(adjustedPrice, sellCap);
  }
  adjustedPrice = Math.max(adjustedPrice, minDefensePrice);

  if (itemClass.includes('희소')) {
    const premiumFloor = Math.max(
      minDefensePrice,
      targetPrice - (targetPrice >= getPriceForMargin(premiumMinMargin) ? 1500 : 1000)
    );
    adjustedPrice = Math.max(adjustedPrice, premiumFloor);
  }

  adjustedPrice = floor100(adjustedPrice);
  if (calcMargin(adjustedPrice) < absoluteMinMargin) {
    adjustedPrice = ceil100(Math.max(adjustedPrice, minDefensePrice));
  }
  return adjustedPrice;
}

// ---------- 8) 타겟 사이즈 필터 ----------
let workingSizes = parsed.sizes.slice();
let sizeFilterApplied = false;
let sizeFilterFallback = false;

if (requestedSizes.length > 0) {
  const filtered = parsed.sizes.filter(s => requestedSizes.includes(String(s.size || '').trim().toUpperCase()));
  if (filtered.length > 0) {
    workingSizes = filtered;
    sizeFilterApplied = true;
  } else {
    workingSizes = parsed.sizes.slice();
    sizeFilterFallback = true;
  }
}

// ---------- 9) 본 계산 시작 ----------
const itemsToSave = [];
const summaryCandidates = [];

for (const s of workingSizes) {
  const size = String(s.size || '').trim();
  if (!size) continue;

  const sellQuotesArray = getQuotesArray(s, 'sell');
  const buyQuotesArray = getQuotesArray(s, 'buy');
  const recentTradesArrayRaw = Array.isArray(s.recent_trades) ? s.recent_trades : [];
  const recentTradesArray = sanitizeRecentTrades(recentTradesArrayRaw);

  const buyQuote = buyQuotesArray.length > 0 ? toNumber(buyQuotesArray[0].price, 0) : 0;
  const sellQuote = sellQuotesArray.length > 0 ? toNumber(sellQuotesArray[0].price, 0) : 0;
  const secondSell = sellQuotesArray.length > 1 ? toNumber(sellQuotesArray[1].price, 0) : 0;
  const thirdSell = sellQuotesArray.length > 2 ? toNumber(sellQuotesArray[2].price, 0) : 0;
  const secondBuy = buyQuotesArray.length > 1 ? toNumber(buyQuotesArray[1].price, 0) : 0;

  const recentTrade = recentTradesArray.length > 0 ? toNumber(recentTradesArray[0].price, 0) : 0;
  const recentTradeAvg = avgPrice(recentTradesArray.slice(0, 5));

  const freshRecentTradeExists = hasFreshRecentTrade(recentTradesArray);
const recentAskTradeAlignmentBonus = getRecentAskTradeAlignmentBonus(sellQuote, recentTradesArray);

const askOnlyIlliquid =
  sellQuote > 0 &&
  buyQuote <= 0 &&
  !freshRecentTradeExists;

const ultraWideSpreadIlliquid =
  sellQuote > 0 &&
  buyQuote > 0 &&
  ((sellQuote - buyQuote) / sellQuote) >= 0.22 &&
  !freshRecentTradeExists;

  const buyMargin = calcMargin(buyQuote);
  const sellMargin = calcMargin(sellQuote);
  const recentMargin = calcMargin(recentTrade);
  const recentAvgMargin = calcMargin(recentTradeAvg);

  const sellQtyTopSum = sumQty(sellQuotesArray.slice(0, 3));
  const buyQtyTopSum = sumQty(buyQuotesArray.slice(0, 3));

  const sellGap12 = (sellQuote > 0 && secondSell > 0) ? (secondSell - sellQuote) : 0;
  const sellGap23 = (secondSell > 0 && thirdSell > 0) ? (thirdSell - secondSell) : 0;
  const buyGap12 = (buyQuote > 0 && secondBuy > 0) ? (buyQuote - secondBuy) : 0;

  const bidAskSpread = (sellQuote > 0 && buyQuote > 0) ? (sellQuote - buyQuote) : 0;
  const bidAskSpreadPct = (sellQuote > 0 && buyQuote > 0) ? ((sellQuote - buyQuote) / sellQuote) : 0;
  const askVsRecentGap = (sellQuote > 0 && recentTradeAvg > 0) ? (sellQuote - recentTradeAvg) : 0;
  const bidVsRecentGap = (buyQuote > 0 && recentTradeAvg > 0) ? (recentTradeAvg - buyQuote) : 0;

  // ---------- 과열 최저호가 감지 ----------
  const stretchedAsk =
    sellQuote > 0 &&
    recentTradeAvg > 0 &&
    sellQuote >= recentTradeAvg * 1.08;

  const mildlyStretchedAsk =
    sellQuote > 0 &&
    recentTradeAvg > 0 &&
    sellQuote >= recentTradeAvg * 1.05;

  const suspiciousPriceStructure = isSuspiciousPriceStructure({
    buyQuote,
    sellQuote,
    recentTradeAvg
  });

  if (suspiciousPriceStructure) {
    const rowData = {
      isError: false,
      timestamp: new Date().toISOString(),
      chatId,
      mediaGroupId,

      상품명: productName,
      상품코드: productCode,
      사이즈: size,

      영산공급가: supply,
      매입물류비: pLog,
      재고리스크비용: inventoryRiskCost,
      크림물류비: kLog,
      총원가: totalCost,

      구매입찰가: buyQuote,
      판매입찰가: sellQuote,
      최근체결가: recentTrade,
      최근체결평균가: recentTradeAvg,

      자동목표마진: 0,
      사용자목표마진: userTargetMargin || 0,
      적용목표마진: 0,
      목표방어선: 0,
      전략목표가: 0,
      안전선비딩마진: safeBiddingMargin,
      베스트후보가: 0,

      추천실행가: 0,
      전략관망가: 0,
      전략관망마진: 0,
      예상정산액: 0,
      최종기대마진: 0,

      즉시청산가: buyQuote,
      즉시청산마진: buyMargin,
      방어상장가: 0,
      방어상장마진: 0,
      보유가치점수: 0,

      리스크보정마진: 0,
      ROI퍼센트: 0,

      상품등급: '❌ 데이터충돌',
      회전등급: '판정불가',

      희소성점수: 0,
      회전율점수: 0,
      매물압력점수: 0,
      수요두께점수: 0,
      기대가치점수: 0,
      종합점수: 0,

      판정: '제외',
      태그: '🔴 RED',
      사유: '판매/구매/체결 화면 인식 충돌 가능성. 가격 구조 비정상으로 분석 제외',
      실행유형: '데이터 오류 의심 / 제외',
      분석버전: SYS_VERSION
    };

    itemsToSave.push({ json: rowData });
    summaryCandidates.push(rowData);
    continue;
  }

  // ---------- 회전/체결 HOT 감지 ----------
  let isHot = false;
  if (recentTradesArray.length > 0) {
    const datesStr = recentTradesArray.map(t => String(t.date_text || '')).join(' ');
    if (datesStr.includes('오늘') || datesStr.includes('시간') || datesStr.includes('분')) isHot = true;
  }

  let rotationScoreLegacy = 0;
  if (buyQuote > 0) rotationScoreLegacy += 2;
  if (recentTrade > 0) rotationScoreLegacy += 2;
  if (sellQuote > 0) rotationScoreLegacy += 1;
  if (isHot) rotationScoreLegacy += 1;

  let rotationClass = '저회전';
  if (rotationScoreLegacy >= 5) rotationClass = isHot ? '🔥HOT(초고회전)' : '고회전';
  else if (rotationScoreLegacy >= 3) rotationClass = '중회전';

  // ---------- 5대 지표 점수 산출 ----------
  let scarcityScore = 0;
  if (sellQuotesArray.length <= 2) scarcityScore += 30;
  else if (sellQuotesArray.length <= 4) scarcityScore += 20;
  else scarcityScore += 10;

  if (sellQtyTopSum <= 3) scarcityScore += 30;
  else if (sellQtyTopSum <= 7) scarcityScore += 20;
  else scarcityScore += 10;

  if (sellGap12 >= 3000) scarcityScore += 20;
  else if (sellGap12 >= 1000) scarcityScore += 10;

  if (askVsRecentGap >= 3000) scarcityScore += 20;
  else if (askVsRecentGap >= 1000) scarcityScore += 10;

  // 최근 체결 대비 최저 판매호가가 너무 높으면 '희소'가 아니라 '과열 외톨이 호가'로 간주
  if (stretchedAsk) scarcityScore -= 22;
  else if (mildlyStretchedAsk) scarcityScore -= 10;

  scarcityScore = clampScore(scarcityScore);

  const recencyRaw = recentTradesArray.slice(0, 5).reduce((sum, t) => sum + tradeRecencyWeight(t.date_text), 0);
  let turnoverScore = Math.min(40, recencyRaw * 12);

  if (recentTradesArray.length >= 5) turnoverScore += 25;
  else if (recentTradesArray.length >= 3) turnoverScore += 18;
  else if (recentTradesArray.length >= 1) turnoverScore += 10;

  if (sellQuote > 0 && recentTradeAvg > 0) {
    const gapFromTrade = Math.abs(sellQuote - recentTradeAvg);
    if (gapFromTrade <= 2000) turnoverScore += 25;
    else if (gapFromTrade <= 5000) turnoverScore += 15;
    else turnoverScore += 5;
  }

 if (buyQuote > 0 && recentTradeAvg > 0 && buyQuote >= recentTradeAvg * 0.97) turnoverScore += 10;

// 최근 체결가와 현재 판매호가가 붙어 있으면 회전 보너스
turnoverScore += recentAskTradeAlignmentBonus;

// 매수 부재 + 최근 체결 부재는 회전 강한 감점
if (askOnlyIlliquid) turnoverScore -= 22;
if (ultraWideSpreadIlliquid) turnoverScore -= 12;

turnoverScore = clampScore(turnoverScore);

  let sellPressureScore = 0;
  if (sellQtyTopSum >= 10) sellPressureScore += 35;
  else if (sellQtyTopSum >= 6) sellPressureScore += 25;
  else if (sellQtyTopSum >= 3) sellPressureScore += 15;
  else sellPressureScore += 5;

  if (sellQuotesArray.length >= 5) sellPressureScore += 20;
  else if (sellQuotesArray.length >= 3) sellPressureScore += 12;

  if (sellGap12 > 0 && sellGap12 <= 1000) sellPressureScore += 20;
  else if (sellGap12 > 0 && sellGap12 <= 3000) sellPressureScore += 10;

  if (sellGap23 > 0 && sellGap23 <= 1000) sellPressureScore += 15;
  else if (sellGap23 > 0 && sellGap23 <= 3000) sellPressureScore += 8;

  if (sellQuote > 0 && recentTradeAvg > 0 && sellQuote <= recentTradeAvg + 1000) sellPressureScore += 10;
  sellPressureScore = clampScore(sellPressureScore);

  let buyDepthScore = 0;
  if (buyQuotesArray.length >= 5) buyDepthScore += 20;
  else if (buyQuotesArray.length >= 3) buyDepthScore += 14;
  else if (buyQuotesArray.length >= 1) buyDepthScore += 8;

  if (buyQtyTopSum >= 8) buyDepthScore += 30;
  else if (buyQtyTopSum >= 4) buyDepthScore += 20;
  else if (buyQtyTopSum >= 1) buyDepthScore += 10;

  const bidSupportRatio = (buyQuote > 0 && recentTradeAvg > 0) ? (buyQuote / recentTradeAvg) : 0;
  if (bidSupportRatio >= 0.98) buyDepthScore += 30;
  else if (bidSupportRatio >= 0.96) buyDepthScore += 20;
  else if (bidSupportRatio >= 0.94) buyDepthScore += 10;

  if (bidAskSpreadPct > 0 && bidAskSpreadPct <= 0.04) buyDepthScore += 20;
else if (bidAskSpreadPct > 0 && bidAskSpreadPct <= 0.07) buyDepthScore += 10;

if (askOnlyIlliquid) buyDepthScore -= 18;
if (ultraWideSpreadIlliquid) buyDepthScore -= 10;

buyDepthScore = clampScore(buyDepthScore);

  // ---------- 기존 상품등급/목표마진 로직 ----------
  const premiumSignalA = recentMargin >= premiumMinMargin;
  const premiumSignalB = buyMargin >= absoluteMinMargin;
  const premiumSignalC = sellMargin >= absoluteMinMargin;
  const premiumSignalD = recentTrade > 0 && sellQuote > 0 ? recentTrade >= sellQuote * 0.97 : false;
  const premiumHitCount = [premiumSignalA, premiumSignalB, premiumSignalC, premiumSignalD].filter(Boolean).length;

  let itemClass = '🗑 가치낮음';
  let autoTargetMargin = absoluteMinMargin;

  if (recentMargin >= premiumHighMargin && premiumHitCount >= 3) {
    itemClass = '💎 희소-강';
    autoTargetMargin = premiumHighMargin;
  } else if (recentMargin >= premiumMinMargin && premiumHitCount >= 2) {
    itemClass = '🔥 희소';
    autoTargetMargin = premiumMinMargin;
  } else if (Math.max(recentMargin, buyMargin, sellMargin) >= standardMidMargin) {
    itemClass = '📦 일반-상';
    autoTargetMargin = standardMidMargin;
  } else if (Math.max(recentMargin, buyMargin, sellMargin) >= absoluteMinMargin) {
    itemClass = '📦 일반';
    autoTargetMargin = absoluteMinMargin;
  } else if (recentTrade > 0 || sellQuote > 0 || buyQuote > 0) {
    itemClass = '🗑 가치낮음';
    autoTargetMargin = absoluteMinMargin;
  } else {
    itemClass = '❔ 데이터부족';
    autoTargetMargin = Math.max(20000, absoluteMinMargin);
  }

  const targetMargin = Math.max(autoTargetMargin, userTargetMargin || 0);
  const targetPrice = getPriceForMargin(targetMargin);
  const minDefensePrice = getPriceForMargin(absoluteMinMargin);

  // ---------- 가격 시뮬레이션 ----------
  let undercutBid = 0;
  let undercutReason = '';

  if (sellQuotesArray.length > 0) {
    const topPrice = toNumber(sellQuotesArray[0].price, 0);
    const topQty = toNumber(sellQuotesArray[0].qty, 1);
    const secondSellPrice = secondSell || 0;

    const canUseTopAskAsScarce =
      topQty === 1 &&
      secondSellPrice > 0 &&
      (secondSellPrice - topPrice >= 2000) &&
      (
        recentTradeAvg <= 0 ||
        topPrice <= recentTradeAvg * 1.04
      );

    // 최근 체결 대비 최저호가가 과열이면, 최저호가를 그대로 전략가로 쓰지 않음
    if (stretchedAsk) {
      undercutBid = Math.min(
        topPrice,
        ceil100(recentTradeAvg + 2500)
      );
      undercutReason = `최저호가가 최근 체결 대비 과열. 최근 체결권 기준 상한 적용 (${won(undercutBid)}원)`;
    } else if (
      sellPressureScore <= 40 &&
      scarcityScore >= 60 &&
      canUseTopAskAsScarce
    ) {
      undercutBid = topPrice;
      undercutReason = `매물압력 낮음·희소성 높음. 1등 동가(${won(undercutBid)}원) 유지`;
    } else if (canUseTopAskAsScarce) {
      undercutBid = topPrice;
      undercutReason = `1등 매물(1개) 허수 간주, 1등 동가(${won(undercutBid)}원) 세팅`;
    } else {
      undercutBid = Math.max(0, ceil100(topPrice) - 1000);
      undercutReason = `최저 판매호가 저항 확인, -1천원 제압 (${won(undercutBid)}원)`;
    }
  } else if (recentTradeAvg > 0) {
    undercutBid = ceil100(recentTradeAvg);
    undercutReason = `경쟁 매물 없음, 최근 평균 체결가(${won(undercutBid)}원) 기준 세팅`;
  } else {
    undercutBid = targetPrice;
    undercutReason = `데이터 부족, 목표 마진가 기준 세팅`;
  }

  const dynamicWaitPrice = getDefensePriceByMarket({
    itemClass,
    targetPrice,
    minDefensePrice,
    sellQuote,
    recentTradeAvg,
    scarcityScore,
    turnoverScore,
    buyDepthScore,
    sellPressureScore,
    absoluteMinMargin,
    premiumMinMargin,
    calcMargin
  });

  const undercutMargin = calcMargin(undercutBid);
  const dynamicWaitMargin = calcMargin(dynamicWaitPrice);

  let bestBidCandidate = 0;
  let bestBidReason = '';

  if (undercutBid > 0 && undercutMargin >= dynamicWaitMargin) {
    bestBidCandidate = undercutBid;
    bestBidReason = undercutReason;
  } else {
    bestBidCandidate = dynamicWaitPrice;
    bestBidReason = `시장점수 반영 방어선 대기 (${won(dynamicWaitMargin)}원 기대)`;
  }

  let expectedFinalMargin = calcMargin(bestBidCandidate);
  let actualExpectedMargin = expectedFinalMargin;

  // ---------- V10.5.3 핵심: 보유가치점수(Hold Value Score) 재설계 ----------
  const immediateExitPrice = buyQuote;
  const immediateExitMargin = buyMargin;
  const defenseListingPrice = minDefensePrice;
  const defenseListingMargin = calcMargin(defenseListingPrice);

  let holdValueScore = 0;

  if (defenseListingMargin >= 40000) holdValueScore += 35;
  else if (defenseListingMargin >= 30000) holdValueScore += 25;
  else if (defenseListingMargin >= 20000) holdValueScore += 15;
  else if (defenseListingMargin >= 15000) holdValueScore += 5;

  if (expectedFinalMargin >= 50000) holdValueScore += 25;
  else if (expectedFinalMargin >= 40000) holdValueScore += 15;
  else if (expectedFinalMargin >= 30000) holdValueScore += 10;

  holdValueScore += Math.round(scarcityScore * 0.20);
  holdValueScore += Math.round((100 - sellPressureScore) * 0.15);
  holdValueScore += Math.round(turnoverScore * 0.05);

  // 최근 체결가와 현재 판매호가가 잘 붙으면 보유가치 가산
  holdValueScore += Math.round(recentAskTradeAlignmentBonus * 0.7);

  // 매수 부재 + 최근 체결 부재 고가매물은 보유가치 강등
  if (askOnlyIlliquid) holdValueScore -= 22;
  if (ultraWideSpreadIlliquid) holdValueScore -= 10;

  holdValueScore = clampScore(holdValueScore);

  const upsideExtraMargin = expectedFinalMargin - immediateExitMargin;

  // ---------- 선매입 vs 선비딩 구분용 보조 조건 ----------
  const weakBidSupport =
    buyQuote <= 0 ||
    buyDepthScore < 20 ||
    (
      recentTradeAvg > 0 &&
      buyQuote > 0 &&
      buyQuote < recentTradeAvg * 0.72
    );

  const poorExitLiquidity =
    weakBidSupport ||
    buyQtyTopSum <= 1;

  const canPrePurchaseSafely =
    !poorExitLiquidity &&
    defenseListingMargin >= 18000 &&
    holdValueScore >= 45;

  const shouldUsePreBidInstead =
    expectedFinalMargin >= safeBiddingMargin &&
    (
      poorExitLiquidity ||
      defenseListingMargin < 18000
    );

  // ---------- 7단 운영모드 판정 ----------
  let recommendedBid = 0;
  let action = '';
  let tag = '';
  let execType = '';
  let reason = '';

  if (
    immediateExitMargin >= 30000 &&
    sellPressureScore <= 55 &&
    holdValueScore >= 40 &&
    (upsideExtraMargin >= 7000 || scarcityScore >= 60 || expectedFinalMargin >= 45000) &&
    (freshRecentTradeExists || immediateExitMargin >= 30000)
  ) {
    recommendedBid = bestBidCandidate;
    actualExpectedMargin = expectedFinalMargin;
    execType = '3일 고가 비딩 → 미체결 시 즉시 체결';
    action = '선매입/관망';
    tag =
      (expectedFinalMargin >= premiumHighMargin && (turnoverScore >= 20 || immediateExitMargin >= 30000))
        ? '💎 DIAMOND'
        : '🔵 BLUE';
    reason = `즉시청산 ${won(immediateExitMargin)}원 가능. 3일 고가 비딩 후 반응 없으면 즉시 체결 전환`;
  }
  else if (
  expectedFinalMargin >= 30000 &&
  holdValueScore >= 45 &&
  sellPressureScore <= 65 &&
  !askOnlyIlliquid &&
  canPrePurchaseSafely &&
  (
    scarcityScore >= 55 ||
    expectedFinalMargin >= 45000 ||
    defenseListingMargin >= 25000 ||
    freshRecentTradeExists ||
    recentAskTradeAlignmentBonus >= 12
  ) &&
  (
    freshRecentTradeExists ||
    immediateExitMargin >= 30000 ||
    recentAskTradeAlignmentBonus >= 16
  )
) {
  recommendedBid = bestBidCandidate;
  actualExpectedMargin = expectedFinalMargin;
  execType = '선매입 후 고가 관망 (마진 쿠션 확보)';
  action = '선매입/관망';
  tag =
    (expectedFinalMargin >= premiumHighMargin && immediateExitMargin >= 20000)
      ? '💎 DIAMOND'
      : '🔵 BLUE';
  reason = defenseListingMargin >= 20000
    ? `고마진 + 하방방어(${won(defenseListingMargin)}원) 확보. 3~7일 고가 비딩 후 필요시 방어청산`
    : `고마진 쿠션(${won(expectedFinalMargin)}원) 기반 관망. 3~7일 고가 비딩 후 반응 없으면 단계적 인하`;
}
  else if (
    expectedFinalMargin >= 40000 &&
    holdValueScore >= 45 &&
    defenseListingMargin >= 18000 &&
    !askOnlyIlliquid &&
    (
      scarcityScore >= 50 ||
      sellPressureScore <= 45 ||
      expectedFinalMargin >= 55000 ||
      freshRecentTradeExists
    )
  ) {
    recommendedBid = bestBidCandidate;
    actualExpectedMargin = expectedFinalMargin;
    execType = '선매입 후 시험 관망 (단계적 인하)';
    action = '선매입/시험관망';
    tag = '🔵 BLUE';
    reason = `수요가 낮아도 하방방어(${won(defenseListingMargin)}원) 튼튼함. 고마진 쿠션 믿고 선매입 베팅`;
  }
  else if (
    buyQuote > 0 &&
    immediateExitMargin >= safeBiddingMargin &&
    (
      immediateExitMargin >= targetMargin ||
      turnoverScore >= 60 ||
      (
        totalCost <= 160000 &&
        immediateExitMargin >= 20000 &&
        recentTradeAvg > 0
      )
    )
  ) {
    recommendedBid = buyQuote;
    actualExpectedMargin = immediateExitMargin;
    execType = '즉시 체결 후 발주 (무재고 타임어택)';
    action = '즉시 체결';
    tag = immediateExitMargin >= premiumMinMargin ? '🔵 BLUE' : '🟢 GREEN';
    reason =
      (totalCost <= 160000 && immediateExitMargin >= 20000 && recentTradeAvg > 0)
        ? `저가/중가 즉시회전 예외 적용. 구매호가로 ${won(immediateExitMargin)}원 확보 후 48시간 내 발주 대응`
        : `구매호가로 ${won(immediateExitMargin)}원 확보. 48시간 내 영산 발주 대응`;
  }
  else if (
    expectedFinalMargin >= premiumMinMargin &&
    turnoverScore >= 45 && buyDepthScore >= 35 && sellPressureScore <= 40 && scarcityScore >= 55
  ) {
    recommendedBid = bestBidCandidate;
    actualExpectedMargin = expectedFinalMargin;
    execType = '선매입 후 비딩 (재고 선확보)';
    action = '선매입';
    tag = '🔵 BLUE';
    reason = `고마진 및 안전지표 충족. 재고 확보 후 비딩 (${won(actualExpectedMargin)}원 기대)`;
  }
  else if (
    (
      shouldUsePreBidInstead &&
      recentTradeAvg > 0 &&
      (
        freshRecentTradeExists ||
        recentAskTradeAlignmentBonus >= 12 ||
        turnoverScore >= 45
      )
    ) ||
    (
      expectedFinalMargin >= safeBiddingMargin &&
      turnoverScore >= 45 &&
      buyDepthScore >= 25 &&
      sellPressureScore <= 55
    )
  ) {
    recommendedBid = bestBidCandidate;
    actualExpectedMargin = expectedFinalMargin;
    execType = '선비딩 후 체결시 발주 (무재고)';
    action = '선비딩';
    tag = '🟡 YELLOW';
    reason = poorExitLiquidity
      ? `최근 체결/판매정렬은 양호하나 현재 매수방어가 약함. 먼저 비딩 반응 확인 후 체결 시 발주 (${won(actualExpectedMargin)}원 기대)`
      : `1.5만 컷 통과 및 회전율 양호. 무재고 덫놓기 (${won(actualExpectedMargin)}원 기대)`;
  }
  else {
    recommendedBid = 0;
    actualExpectedMargin = expectedFinalMargin;
    execType = '관망 / 패스';
    action = '패스';
    if (expectedFinalMargin < safeBiddingMargin) {
      tag = '🔴 RED';
      reason = `기대마진(${won(expectedFinalMargin)}원) 1.5만 미만. 48시간 발주 리스크 초과`;
    } else {
      tag = '🟠 ORANGE';
      reason = askOnlyIlliquid
        ? `판매호가만 높고 최근 체결/매수세 확인 부족. 실현 가능성 낮아 패스`
        : `마진은 나오나 하방방어/회전율 취약. 악성재고 위험으로 패스`;
    }
  }

  // ---------- EV 점수 ----------
  let expectedValueScore = 0;
  if (actualExpectedMargin >= 50000) expectedValueScore += 42;
  else if (actualExpectedMargin >= 40000) expectedValueScore += 34;
  else if (actualExpectedMargin >= 30000) expectedValueScore += 26;
  else if (actualExpectedMargin >= 20000) expectedValueScore += 17;
  else if (actualExpectedMargin >= safeBiddingMargin) expectedValueScore += 7;

  if (targetMargin > 0) {
    const targetAchieveRatio = actualExpectedMargin / targetMargin;
    if (targetAchieveRatio >= 1.0) expectedValueScore += 24;
    else if (targetAchieveRatio >= 0.9) expectedValueScore += 16;
    else if (targetAchieveRatio >= 0.8) expectedValueScore += 8;
    else if (targetAchieveRatio >= 0.65) expectedValueScore += 3;
  }

  const roiPct = totalCost > 0 ? (actualExpectedMargin / totalCost) * 100 : 0;
  if (roiPct >= 15) expectedValueScore += 18;
  else if (roiPct >= 12) expectedValueScore += 14;
  else if (roiPct >= 9) expectedValueScore += 10;
  else if (roiPct >= 6) expectedValueScore += 6;
  else if (roiPct >= 4) expectedValueScore += 2;

  const liquidityModifier = clamp(
    ((turnoverScore * 0.40) + (buyDepthScore * 0.25) + (scarcityScore * 0.15) - (sellPressureScore * 0.20)) / 100,
    0.25,
    0.95
  );
  const riskAdjustedMargin = actualExpectedMargin * liquidityModifier;

  if (riskAdjustedMargin >= 50000) expectedValueScore += 16;
  else if (riskAdjustedMargin >= 30000) expectedValueScore += 12;
  else if (riskAdjustedMargin >= 20000) expectedValueScore += 8;
  else if (riskAdjustedMargin >= 10000) expectedValueScore += 4;

  expectedValueScore = clampScore(expectedValueScore);

  // ---------- 즉시청산 보너스 추가 ----------
  let immediateExitScore = 0;
  if (immediateExitMargin >= 40000) immediateExitScore = 100;
  else if (immediateExitMargin >= 30000) immediateExitScore = 85;
  else if (immediateExitMargin >= 20000) immediateExitScore = 65;
  else if (immediateExitMargin >= 15000) immediateExitScore = 45;
  else if (immediateExitMargin >= 10000) immediateExitScore = 25;

  let immediateRotationBonus = 0;

  // 저가/중가 상품에서 즉시 체결 가능한 회전 카드 가산
  if (
    buyQuote > 0 &&
    totalCost <= 160000 &&
    immediateExitMargin >= 20000
  ) {
    immediateRotationBonus += 18;
  } else if (
    buyQuote > 0 &&
    totalCost <= 190000 &&
    immediateExitMargin >= 18000
  ) {
    immediateRotationBonus += 10;
  }

  // 최근 체결까지 있으면 추가 가산
  if (
    buyQuote > 0 &&
    immediateExitMargin >= 20000 &&
    recentTradeAvg > 0
  ) {
    immediateRotationBonus += 8;
  }

  // 즉시 체결 실행으로 확정된 경우 한 번 더 소폭 가산
  if (execType === '즉시 체결 후 발주 (무재고 타임어택)') {
    immediateRotationBonus += 22;
  }

  immediateRotationBonus = clampScore(immediateRotationBonus);

  let overallScore = clampScore(
    scarcityScore * 0.10 +
    turnoverScore * 0.15 +
    (100 - sellPressureScore) * 0.15 +
    buyDepthScore * 0.13 +
    expectedValueScore * 0.20 +
    holdValueScore * 0.10 +
    immediateExitScore * 0.09 +
    immediateRotationBonus * 0.18
  );

  // 패스 카드(ORANGE)는 실행 가능 카드와 점수 위계를 분리하기 위해 소폭 감점
  if (tag === '🟠 ORANGE') {
    overallScore = Math.max(0, overallScore - 6);
  }

  const finalSettlement = calcSettlement(recommendedBid, feeMultiplier, fixedFeeWithVat);

  const rowData = {
    isError: false,
    timestamp: new Date().toISOString(),
    chatId,
    mediaGroupId,

    상품명: productName,
    상품코드: productCode,
    사이즈: size,

    영산공급가: supply,
    매입물류비: pLog,
    재고리스크비용: inventoryRiskCost,
    크림물류비: kLog,
    총원가: totalCost,

    구매입찰가: buyQuote,
    판매입찰가: sellQuote,
    최근체결가: recentTrade,
    최근체결평균가: recentTradeAvg,

    구매입찰마진: buyMargin,
    판매입찰마진: sellMargin,
    최근체결기준마진: recentMargin,
    최근평균체결기준마진: recentAvgMargin,

    sell_qty_top_sum: sellQtyTopSum,
    buy_qty_top_sum: buyQtyTopSum,
    bid_ask_spread: bidAskSpread,
    bid_ask_spread_pct: Number(bidAskSpreadPct.toFixed(4)),
    ask_vs_recent_gap: askVsRecentGap,
    bid_vs_recent_gap: bidVsRecentGap,
    buy_gap_1_2: buyGap12,

    자동목표마진: autoTargetMargin,
    사용자목표마진: userTargetMargin || 0,
    적용목표마진: targetMargin,
    목표방어선: minDefensePrice,
    전략목표가: targetPrice,
    안전선비딩마진: safeBiddingMargin,
    베스트후보가: bestBidCandidate,

    추천실행가: recommendedBid,
    전략관망가: bestBidCandidate,
    전략관망마진: expectedFinalMargin,
    예상정산액: finalSettlement,
    최종기대마진: actualExpectedMargin,

    즉시청산가: immediateExitPrice,
    즉시청산마진: immediateExitMargin,
    방어상장가: defenseListingPrice,
    방어상장마진: defenseListingMargin,
    보유가치점수: holdValueScore,

    리스크보정마진: Math.round(riskAdjustedMargin),
    ROI퍼센트: Number(roiPct.toFixed(2)),

    상품등급: itemClass,
    회전등급: rotationClass,

    희소성점수: scarcityScore,
    회전율점수: turnoverScore,
    매물압력점수: sellPressureScore,
    수요두께점수: buyDepthScore,
    기대가치점수: expectedValueScore,
    종합점수: overallScore,

    판정: action,
    태그: tag,
    사유: reason,
    실행유형: execType,
    분석버전: SYS_VERSION
  };

  itemsToSave.push({ json: rowData });
  summaryCandidates.push(rowData);
}

// ---------- 10) 정렬 (실행우선순위 복구) ----------
function execPriorityScore(execType) {
  if (String(execType).includes('즉시 체결 후 발주')) return 5;
  if (String(execType).includes('3일 고가 비딩 → 미체결 시 즉시 체결')) return 4;
  if (String(execType).includes('선매입 후 고가 관망')) return 3;
  if (String(execType).includes('선매입 후 시험 관망')) return 2;
  if (String(execType).includes('선비딩 후 체결시 발주')) return 1;
  return 0;
}

summaryCandidates.sort((a, b) => {
  // 1순위: 태그 점수
  if (tagScore(b.태그) !== tagScore(a.태그)) {
    return tagScore(b.태그) - tagScore(a.태그);
  }

  // 2순위: 실행 우선순위
  if (execPriorityScore(b.실행유형) !== execPriorityScore(a.실행유형)) {
    return execPriorityScore(b.실행유형) - execPriorityScore(a.실행유형);
  }

  // 3순위: 종합점수
  if (b.종합점수 !== a.종합점수) {
    return b.종합점수 - a.종합점수;
  }

  // 4순위: 최종 기대마진
  return b.최종기대마진 - a.최종기대마진;
});

// ---------- 11) 텔레그램 브리핑 ----------
let summaryText = `📊 *KREAM 보유전략 분석 [${SYS_VERSION}]*\n`;
summaryText += `*${productName}*\n`;
if (productCode) summaryText += `(상품코드: ${productCode})\n`;
summaryText += `(원가: ${won(totalCost)}원 | 최소 안전마진: ${won(safeBiddingMargin)}원)\n`;

if (sizeConflictNotes.length > 0) {
  summaryText += `⚠️ ${sizeConflictNotes.join(' / ')}\n`;
}

const globalNotes = Array.isArray(parsed.global_notes) ? parsed.global_notes.filter(Boolean) : [];
if (globalNotes.length > 0) {
  summaryText += `⚠️ AI 추출 주의: ${globalNotes.join(' / ')}\n`;
}

if (userTargetMargin > 0) summaryText += `(🎯 사용자 목표마진: ${won(userTargetMargin)}원 반영)\n`;
if (sizeFilterApplied) summaryText += `(🔍 타겟 필터 적용: ${requestedSizes.join(', ')})\n`;
else if (sizeFilterFallback) summaryText += `(⚠️ 입력한 사이즈 매물이 없어 전체 분석)\n`;
summaryText += `\n`;

const viableCandidates = summaryCandidates.filter(row => !String(row.태그).includes('RED') && !String(row.태그).includes('ORANGE'));

if (viableCandidates.length === 0) {
  summaryText += '⚠️ *[전량 패스 권고]* 해당 상품은 발주 리스크를 감수하거나 재고로 떠안을 만한 하방 방어력/안전마진을 갖춘 사이즈가 없습니다.\n\n';
  for (const row of summaryCandidates.slice(0, 5)) {
    summaryText += `🔹 *${row.사이즈}* (${row.태그})\n`;
    summaryText += `🏆 종합점수: *${row.종합점수}점*\n`;
    summaryText += `👉 실행: *${row.실행유형}*\n`;
    if (row.추천실행가 > 0) {
      summaryText += `추천가: ${won(row.추천실행가)}원 | 💰 마진: *${won(row.최종기대마진)}원*\n`;
    } else {
      summaryText += `관망기준가: ${won(row.전략관망가)}원 | 예상마진 기준: *${won(row.전략관망마진)}원*\n`;
    }
    summaryText += `📈 지표: [희소 ${row.희소성점수}] [회전 ${row.회전율점수}] [압력 ${row.매물압력점수}] [매수두께 ${row.수요두께점수}] [EV ${row.기대가치점수}] [보유 ${row.보유가치점수}]\n`;
    summaryText += `(근거: ${row.사유})\n\n`;
  }
} else {
  for (const row of summaryCandidates.slice(0, 5)) {
    summaryText += `🔹 *${row.사이즈}* (${row.태그})\n`;
    summaryText += `🏆 종합점수: *${row.종합점수}점*\n`;
    summaryText += `👉 실행: *${row.실행유형}*\n`;
    if (row.추천실행가 > 0) {
      summaryText += `추천가: ${won(row.추천실행가)}원 | 💰 마진: *${won(row.최종기대마진)}원*\n`;
    } else {
      summaryText += `관망기준가: ${won(row.전략관망가)}원 | 예상마진 기준: *${won(row.전략관망마진)}원*\n`;
    }
    summaryText += `📈 지표: [희소 ${row.희소성점수}] [회전 ${row.회전율점수}] [압력 ${row.매물압력점수}] [매수두께 ${row.수요두께점수}] [EV ${row.기대가치점수}] [보유 ${row.보유가치점수}]\n`;
    summaryText += `(근거: ${row.사유})\n\n`;
  }
}

if (itemsToSave.length > 0) {
  itemsToSave[0].json.telegramSummary = summaryText;
}

return itemsToSave;

nodes.executeCode:
const geminiItem = $items("HTTP: Gemini (상품/시세 추출)")[0];
const mergeNode = $items("If: 병합 정상 확인")[0].json;
const chatId = mergeNode.chatId || '';
const mediaGroupId = mergeNode.mediaGroupId || '';
const SYS_VERSION = 'V7.0 (DB 자동매칭)';

let parsed;
try {
  const rawText = geminiItem.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
  parsed = JSON.parse(String(rawText).replace(/```json|```/g, '').trim());
} catch (e) {
  return [{ json: { isError: true, chatId, telegramSummary: '❗️AI 파싱 오류. 이미지를 다시 전송해주세요.' } }];
}

if (!parsed || !Array.isArray(parsed.sizes) || parsed.sizes.length === 0) {
  return [{ json: { isError: true, chatId, telegramSummary: '❗️사이즈 데이터를 추출하지 못했습니다.' } }];
}

const productName = String(parsed.product_name || '').trim();
const priceList = $input.all().map(item => item.json);
let matchedRow = null;

// 단가표에서 상품명 유사도 매칭 (띄어쓰기 무시)
for (const row of priceList) {
  const rowName = String(row['품목'] || '').replace(/\s+/g, '').toLowerCase();
  const pName = productName.replace(/\s+/g, '').toLowerCase();
  if (rowName && (pName.includes(rowName) || rowName.includes(pName))) {
    matchedRow = row;
    break;
  }
}

if (!matchedRow) {
  return [{ json: { isError: true, chatId, telegramSummary: `❗️[매칭 실패] 단가표에 없는 상품입니다.\n\n인식된 상품: ${productName}\n\n구글 시트 '단가표' 탭에 해당 상품의 영산공급가를 추가하신 뒤 다시 사진을 전송해주세요.` } }];
}

function toNumber(val, def = 0) {
  if (val === null || val === undefined || val === '') return def;
  const num = Number(String(val).replace(/,/g, '').trim());
  return Number.isFinite(num) ? num : def;
}
function ceil100(value) { return Math.ceil(value / 100) * 100; }
function won(value) { return Number(value || 0).toLocaleString('ko-KR'); }

const supply = toNumber(matchedRow['영산공급가'], 0);
const tMargin = toNumber(matchedRow['목표마진'], 10000);
const pLog = 3500; // 매입 물류비 고정
const kLog = 3500; // 크림 물류비 고정

if (supply <= 0) return [{ json: { isError: true, chatId, telegramSummary: `❗️'단가표'에 ${productName}의 공급가가 0원입니다.` } }];

const totalCost = supply + pLog;
const feeMultiplier = 0.934;
const fixedFeeWithVat = 2750;
const itemsToSave = [];
const summaryCandidates = [];

for (const s of parsed.sizes) {
  const size = String(s.size || '').trim();
  if (!size) continue;

  const buyQuote = toNumber(s.buy_quote, 0);
  const sellQuote = toNumber(s.sell_quote, 0);
  const recentTrade = toNumber(s.recent_trade, 0);

  const targetBid = ceil100((totalCost + kLog + tMargin + fixedFeeWithVat) / feeMultiplier);

  let recommendedBid = targetBid;
  let tag = '🔴 레드';
  let action = '제외';
  let feasibility = '보통';
  let reason = '';
  let execType = '판매입찰 대기'; 

  const emptyCount = (buyQuote === 0 ? 1 : 0) + (sellQuote === 0 ? 1 : 0) + (recentTrade === 0 ? 1 : 0);

  if (emptyCount >= 2) {
    feasibility = '정보 부족';
    action = '관망';
    reason = '[관망-정보부족] 호가 및 체결 데이터 부족';
  } else {
    const instantSettlement = Math.floor(buyQuote * feeMultiplier) - fixedFeeWithVat;
    const instantMargin = instantSettlement - totalCost - kLog;

    if (buyQuote > 0 && buyQuote >= targetBid && instantMargin >= tMargin) {
      recommendedBid = buyQuote;
      feasibility = '즉시 체결 가능';
      action = '즉시 진행';
      tag = '🔵 BLUE';
      execType = '즉시 판매';
      reason = '[즉시진행] 구매호가가 목표가 이상';
    } else if (sellQuote > 0 && targetBid >= sellQuote) {
      recommendedBid = targetBid;
      feasibility = '경쟁 매물 존재';
      action = '관망';
      reason = '[관망-경쟁가열] 최저 판매호가가 내 목표가보다 낮음';
    } else {
      recommendedBid = targetBid;
      if (recentTrade > 0 && recommendedBid > recentTrade) {
        feasibility = '괴리 발생';
        action = '관망';
        reason = '[관망-괴리발생] 추천입찰가가 최근체결가 초과';
      } else if (sellQuote > 0 && recommendedBid >= sellQuote) {
        feasibility = '판매호가 초과';
        action = '관망';
        reason = '[관망-판매호가초과] 목표입찰가가 최저 판매호가 초과';
      } else if (buyQuote > 0 && buyQuote < targetBid) {
        feasibility = '수익 대기';
        action = '관망';
        reason = '[관망-수익대기] 시장가 낮음. 목표가 덫 놓기';
      }
    }
  }

  const settlement = Math.floor(recommendedBid * feeMultiplier) - fixedFeeWithVat;
  const finalMargin = settlement - totalCost - kLog;

  if (action !== '즉시 진행' && action !== '관망') {
    if (finalMargin >= 30000) {
      tag = '🔵 BLUE';
      action = '우선 검토';
      reason = reason || '3만원 이상 마진 확보';
    } else if (finalMargin >= 10000) {
      tag = '🟢 GREEN';
      action = '일반 비딩';
      reason = reason || '1만원 이상 마진 확보';
    } else {
      tag = '🔴 레드';
      action = '제외';
      feasibility = '낮음';
      reason = reason || '최소 마진 미달';
    }
  } else if (action === '관망') {
    tag = finalMargin >= 10000 ? '🟢 GREEN' : '🔴 레드';
  }

  const rowData = {
    isError: false, timestamp: new Date().toISOString(), chatId, mediaGroupId,
    상품명: productName, 사이즈: size, 영산공급가: supply, 매입물류비: pLog, 크림물류비: kLog,
    계: totalCost, 목표마진: tMargin, 구매입찰가: buyQuote, 판매입찰가: sellQuote, 최근체결가: recentTrade,
    목표입찰가: targetBid, 추천실행가: recommendedBid, 예상정산액: settlement, 최종마진: finalMargin,
    판정: action, 태그: tag, 체결가능성: feasibility, 사유: reason, 
    실행유형: execType, 분석버전: SYS_VERSION
  };

  itemsToSave.push({ json: rowData });

  if (['즉시 진행', '우선 검토', '일반 비딩', '관망'].includes(action) && tag !== '🔴 레드' && feasibility !== '정보 부족') {
    summaryCandidates.push(rowData);
  }
}

summaryCandidates.sort((a, b) => {
  const score = (x) => x.판정 === '즉시 진행' ? 4 : x.판정 === '우선 검토' ? 3 : x.판정 === '일반 비딩' ? 2 : 1;
  if (score(b) !== score(a)) return score(b) - score(a);
  return b.최종마진 - a.최종마진;
});

let summaryText = `📊 *KREAM 자동매칭 [${SYS_VERSION}]: ${productName}*\n`;
summaryText += `(계: ${won(totalCost)} | 마진목표: ${won(tMargin)})\n\n`;

if (summaryCandidates.length === 0) {
  summaryText += '⚠️ 타겟 마진을 충족하거나 실행 가능한 사이즈가 없습니다.\n';
} else {
  const topRows = [];
  const waitingRows = [];

  for (const row of summaryCandidates) {
    if (row.판정 === '관망') waitingRows.push(row);
    else topRows.push(row);
  }
  const finalRows = [...topRows, ...waitingRows.slice(0, 2)].slice(0, 5);

  for (const row of finalRows) {
    summaryText += `🔹 *${row.사이즈}* (${row.태그} / ${row.판정})\n`;
    summaryText += `👉 실행방식: *${row.실행유형}*\n`;
    summaryText += `실행가: ${won(row.추천실행가)}원 | 예상마진: ${won(row.최종마진)}원\n`;
    summaryText += `(상태: ${row.체결가능성})\n\n`;
  }
}

if (itemsToSave.length > 0) itemsToSave[0].json.telegramSummary = summaryText;
return itemsToSave;
